const out = [];
for (const c of comps) {
  const page = c.parent && c.parent.type === 'PAGE' ? c.parent.name : (c.parent ? c.parent.name : '?');
  out.push({ id: c.id, name: c.name, page: page, w: c.width, h: c.height, key: c.key });
}
return JSON.stringify(out);

// Read-only inspection: describe styling of Button, Text Field, Status Bar, Home Indicator
function describe(n, depth) {
  if (depth > 3) return null;
  const d = { id: n.id, name: n.name, type: n.type, x: n.x, y: n.y, w: Math.round(n.width), h: Math.round(n.height) };
  if ('fills' in n && Array.isArray(n.fills) && n.fills.length) {
    d.fills = n.fills.filter(f => f.type === 'SOLID' || f.type === 'GRADIENT_LINEAR').map(f => f.type === 'SOLID' ? { c: JSON.stringify(f.color), o: f.opacity } : f.type);
  }
  if ('strokes' in n && n.strokes.length) d.strokes = n.strokes.map(s => JSON.stringify(s));
  if ('cornerRadius' in n) d.radius = n.cornerRadius;
  if (n.type === 'TEXT') { d.font = n.fontName; d.chars = n.characters; d.fontSize = n.fontSize; d.fill = JSON.stringify((n.fills && n.fills[0]) || null); }
  if ('children' in n) d.children = n.children.map(c => describe(c, depth + 1)).filter(Boolean);
  return d;
}
const ids = ['1:24', '1:27', '1:32', '1:42'];
const out = {};
for (const id of ids) {
  const node = await figma.getNodeByIdAsync(id);
  out[node.name] = describe(node, 0);
}
return JSON.stringify(out);

