// Read-only: inspect logo + badge + avatar structures fully
function walk(n, d, out) {
  if (d > 4) return;
  let fillDesc = 'none';
  if ('fills' in n && Array.isArray(n.fills)) {
    fillDesc = n.fills.map(f => f.type === 'SOLID'
      ? '#'+[f.r,f.g,f.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('')
      : f.type).join('|');
  }
  out.push(n.name + ' [' + n.type + '] ' + fillDesc + ' ' + Math.round(n.width) + 'x' + Math.round(n.height));
  if ('children' in n) n.children.forEach(c => walk(c, d+1, out));
}
const out = [];
for (const id of ['1:248','1:249','1:183']) {
  const n = await figma.getNodeByIdAsync(id);
  out.push('=== ' + n.name + ' ===');
  walk(n, 0, out);
}
return out.join('\n');

