async function icon(id,size,hex){const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();i.resize(size,size);if(hex){const v=i.findOne(n=>n.type==='VECTOR');if(v)v.fills=[H(hex)];}return i;}
function T(chars,fam,style,size,hex,o={}){const t=figma.createText();t.fontName={family:fam,style};t.characters=chars;t.fontSize=size;t.fills=[H(hex,o.o??1)];if(o.ls)t.letterSpacing={value:o.ls,unit:'PIXELS'};if(o.lh)t.lineHeight={value:o.lh,unit:'PIXELS'};if(o.w){t.textAutoResize='HEIGHT';t.resize(o.w,t.height);}else{t.textAutoResize='WIDTH_AND_HEIGHT';}if(o.ta)t.textAlignHorizontal=o.ta;return t;}
function comp(name,w,h){const c=figma.createComponent();c.name=name;if(w!==undefined){c.resizeWithoutConstraints(w,h);}c.fills=[];c.clipsContent=false;return c;}
function cardComp(name,w,h,fill,rad=20,stroke=null){const c=comp(name,w,h);c.cornerRadius=rad;c.fills=[H(fill)];if(stroke){c.strokes=[H(stroke)];c.strokeWeight=1;}c.effects=SHADOW(6,18,0.07);return c;}
function place(c,x,y,txt){c.x=x;c.y=y;ws.appendChild(c);if(txt){const t=T(txt,'Nunito','Regular',11,C.mute);t.x=x;t.y=y+c.height+8;ws.appendChild(t);}return c;}
