function stackV(name,gap){const f=figma.createFrame();f.name=name;f.fills=[];f.layoutMode='VERTICAL';f.primaryAxisSizingMode='AUTO';f.counterAxisSizingMode='AUTO';f.itemSpacing=gap;f.clipsContent=false;return f;}
